"""Music: one instrumental score for the whole film, generated by Lyria (Gemini API).

The prompt is built from the storyboard's music block: the caption, tempo, key and the cues,
placed at the time each cue's shot starts, so the music follows the story. The result is cached
by model + prompt, converted to outputs/music/score.wav, and the film stage mixes it under the
voice (ducked: the music dips while Abba speaks). If no Lyria model answers, the film keeps its
placeholder drone.
"""
from __future__ import annotations

import shutil
import subprocess
from typing import Any

from pipeline.common import (OUT, ROOT, cache_key, call_model, env, ffmpeg, gemini_client,
                             load_storyboard, log_call)

MODELS = [m.strip() for m in (env("MUSIC_MODELS", "lyria-3-pro-preview,lyria-3.5,lyria-3-clip-preview") or "").split(",") if m.strip()]
FOLDER = OUT / "music"


def mmss(t: float) -> str:
    return f"{int(t) // 60}:{int(t) % 60:02}"


def prompt_for(board: dict[str, Any]) -> str:
    import json
    from pipeline import radio
    from pipeline.film import END_CARD
    m = board["music"]
    manifest_path = OUT / "narration" / "manifest.json"   # real lengths: a long line stretches its shot
    manifest = json.loads(manifest_path.read_text(encoding="utf-8")) if manifest_path.exists() else {}
    lengths = radio.shot_lengths(board, manifest)
    starts, t = {}, 0.0
    for shot in board["shots"]:
        starts[shot["id"]] = t
        t += lengths[shot["id"]]
    total = t + END_CARD
    timeline = "; ".join(f"at {mmss(starts[c['at_shot']])} {c['description']}" for c in m["cues"])
    return (f"Compose an instrumental film score, about {round(total)} seconds long. "
            f"{m['caption']}. Tempo {m['bpm']} BPM, key of {m['key']}. "
            f"Timeline: {timeline}. "
            "It sits under a spoken voice, so keep it gentle and spacious with no vocals, "
            "no lyrics and no sudden loud hits; end softly.")


def generate(model: str, prompt: str) -> tuple[bytes, str]:
    from google.genai import types
    client = gemini_client(timeout_s=300)
    reply = client.models.generate_content(
        model=model, contents=[prompt],
        config=types.GenerateContentConfig(response_modalities=["AUDIO"]))
    for part in reply.candidates[0].content.parts:
        if getattr(part, "inline_data", None) and part.inline_data.data:
            return part.inline_data.data, part.inline_data.mime_type or "audio/mpeg"
    raise RuntimeError("no audio in the reply")


def to_wav(raw: bytes, mime: str, out) -> None:
    """Whatever format Lyria returns, store a 48 kHz stereo WAV the film stage can mix."""
    tmp = FOLDER / "_raw.bin"
    tmp.write_bytes(raw)
    cmd = [ffmpeg(), "-y", "-loglevel", "error"]
    if "l16" in mime.lower() or "pcm" in mime.lower():   # raw PCM: e.g. audio/L16;rate=48000;channels=2
        params = dict(p.split("=") for p in mime.replace(" ", "").split(";")[1:] if "=" in p)
        cmd += ["-f", "s16le", "-ar", params.get("rate", "48000"), "-ac", params.get("channels", "2")]
    cmd += ["-i", str(tmp), "-ar", "48000", "-ac", "2", str(out)]
    subprocess.run(cmd, check=True)


def run(board: dict[str, Any] | None = None) -> None:
    board = board or load_storyboard()
    FOLDER.mkdir(parents=True, exist_ok=True)
    prompt = prompt_for(board)
    print("music prompt:\n  " + prompt + "\n")
    for model in MODELS:
        key = cache_key(stage="music", model=model, prompt=prompt)
        cached = FOLDER / f"score-{key}.wav"
        if cached.exists():
            log_call(stage="music", shot="-", provider="cache", model=model, status="hit", file=cached.name)
            break
        try:
            raw, mime = call_model("music", "-", "gemini", model, {"prompt": prompt}, lambda m=model: generate(m, prompt),
                                   attempts=2)
        except Exception as exc:  # noqa: BLE001 - no quota or overloaded: next model
            print(f"  {model} unavailable ({str(exc)[:120]})")
            continue
        to_wav(raw, mime, cached)
        print(f"  wrote {cached.relative_to(ROOT).as_posix()} ({model}, {mime})")
        break
    else:
        import json
        from pipeline import radio, score
        from pipeline.film import END_CARD
        manifest = json.loads((OUT / "narration" / "manifest.json").read_text(encoding="utf-8"))
        lengths = radio.shot_lengths(board, manifest)
        key = cache_key(stage="score", version=score.VERSION, music=board["music"], lengths=lengths, end=END_CARD)
        cached = FOLDER / f"score-tizita-{key}.wav"
        if not cached.exists():
            print("no music model answered: composing the score in code (tizita mode, pipeline/score.py)")
            tmp = cached.with_name(cached.stem + ".partial.wav")
            score.compose_for(board, lengths, END_CARD, tmp)
            tmp.replace(cached)                            # complete files only (FAILURES F18)
        log_call(stage="music", shot="-", provider="local", model="score.py (tizita)", status="ok", file=cached.name)
    shutil.copyfile(cached, FOLDER / "score.wav")
    from pathlib import Path
    import wave
    with wave.open(str(cached)) as w:
        seconds = w.getnframes() / w.getframerate()
    print(f"score: outputs/music/score.wav ({seconds:.0f}s). Run `python -m pipeline film` to use it.")
    if seconds < 60:
        print("  (shorter than the film: it will loop; the fade-out hides the end)")
